for n in N_range:
    start_x = n + 1
    for x in range(start_x, X_upper_bound + 1):
        # Calculate LHS = x^n + x
        lhs = x**n + x

        # We need to check if lhs = 2^k + 2, which means lhs - 2 = 2^k
        target = lhs - 2

        if is_power_of_two(target):
            # Find k such that 2^k = target
