import math

def is_power_of_two(N):
    return N > 0 and (N & (N - 1) == 0)

def solve_equation(x, n):
    LHS_minus_2 = x**n + x - 2
    if not is_power_of_two(LHS_minus_2):
        return None

    k = int(math.log2(LHS_minus_2))
    return k

def check_mod4_constraints(x, n, k):
    # W3 constraints for n >= 3

    # 1. x = 0 mod 4
    if x % 4 == 0:
        return k == 1

    # 2. x = 1 mod 4
    elif x % 4 == 1:
        return k >= 2

    # 3. x = 2 mod 4
    elif x % 4 == 2:
        return k >= 2

    # 4. x = 3 mod 4
    elif x % 4 == 3:
        if n % 2 == 0: # n is even
            return k == 1
        else: # n is odd
            return k >= 2
    return False # Should not happen

solutions = []
# Iterate x from 3 to 10 (since x > n >= 2, smallest interesting case is x=3, n=2, but we focus on n>=3)
# We check all pairs where 3 <= n < x <= 10
for x in range(3, 11):
    for n in range(3, x):
        k = solve_equation(x, n)

        if k is not None:
            # Found a power of 2, now check the modulo 4 constraint
            if check_mod4_constraints(x, n, k):
                solutions.append((x, n, k))

print("Solutions satisfying both equation and modulo 4 constraints (3 <= n < x <= 10):")
for sol in solutions:
    print(sol)
